const originalNodes=new WeakMap(), originalAttrs=new WeakMap();
function lang(){let x=localStorage.getItem('plot_ui_language')||'en';return LANGS.some(v=>v[0]===x)?x:'en'}
function trStatic(src,l=lang()){let x=STATIC[src]||STATIC2[src];return x?(x[l]||x.en||src):src}
function t(key,vars={},l=lang()){let pack=Object.assign({},UI.en,EXTRA.en,ACTION.en,MISC.en,UI[l]||{},EXTRA[l]||{},ACTION[l]||{},MISC[l]||{}),x=pack[key]||key;Object.keys(vars).forEach(k=>x=x.replaceAll('{'+k+'}',String(vars[k])));return x}
function topic(key,l=lang()){return TOPICS[key]?(TOPICS[key][l]||TOPICS[key].en||key):key}
function apply(root=document,l=lang()){
 document.documentElement.lang=l;document.documentElement.dir=l==='he'?'rtl':'ltr';
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
 let n;while(n=walker.nextNode()){if(n.parentElement&&['SCRIPT','STYLE','OPTION'].includes(n.parentElement.tagName))continue;if(!originalNodes.has(n))originalNodes.set(n,n.nodeValue);let raw=originalNodes.get(n),trim=raw.trim();if(trim&&(STATIC[trim]||STATIC2[trim]))n.nodeValue=raw.replace(trim,trStatic(trim,l))}
 root.querySelectorAll?.('[placeholder]').forEach(el=>{if(!originalAttrs.has(el))originalAttrs.set(el,el.getAttribute('placeholder'));let src=originalAttrs.get(el);if(STATIC[src]||STATIC2[src])el.setAttribute('placeholder',trStatic(src,l))});
}
function setLanguage(l){if(!LANGS.some(v=>v[0]===l))l='en';localStorage.setItem('plot_ui_language',l);let sel=document.getElementById('languageSelect');if(sel)sel.value=l;apply(document,l)}
function fillSelector(){let s=document.getElementById('languageSelect');if(!s)return;s.innerHTML=LANGS.map(x=>'<option value="'+x[0]+'">'+x[1]+'</option>').join('');s.value=lang()}
